      "request": [{ "name": "list", "url": "{base}/search?q={keyword|encode}" }],
      "items": "div.comics-card",
      "id": {
        "select": "a.comics-card__poster",
        "attr": "href",
        "transform": ["stripPrefix:/comic/"]
      },
      "fields": {
        "title": [
          { "select": "a.comics-card__poster", "attr": "title" },
          { "select": "a.comics-card__info h3" },
          { "default": "{itemId}" }
        ],
        "cover": { "select": "a.comics-card__poster amp-img", "attr": "src" },
        "author": { "select": "a.comics-card__info small.tags" }
      }
    },
    "category": {
      "request": [{ "name": "list", "url": "{categoryUrl}" }],
      "items": "div.comics-card",
      "id": {
        "select": "a.comics-card__poster",
        "attr": "href",
        "transform": ["stripPrefix:/comic/"]
      },
      "fields": {
        "title": [
          { "select": "a.comics-card__poster", "attr": "title" },
          { "select": "a.comics-card__info h3" },
          { "default": "{itemId}" }
        ],
        "cover": { "select": "a.comics-card__poster amp-img", "attr": "src" },
        "author": { "select": "a.comics-card__info small.tags" }
      }
    },
    "detail": {
      "request": [{ "name": "page", "url": "{base}/comic/{comicId}" }],
      "comic": {
        "title": [
          { "select": "h1.comics-detail__title" },
          { "default": "包子漫画 {comicId}" }
