        "author": { "select": "h2.comics-detail__author" },
        "intro": { "select": "p.comics-detail__desc", "transform": ["stripTags"] },
        "cover": { "select": "div.de-info__box amp-img", "attr": "src" },
        "status": [
          { "select": ".tag-list span.tag", "contains": "完结", "then": "finish", "else": "" },
          { "select": ".tag-list span.tag", "contains": "完結", "then": "finish", "else": "" },
          { "select": ".tag-list span.tag", "contains": "连载", "then": "serial", "else": "" },
          { "select": ".tag-list span.tag", "contains": "連載", "then": "serial", "else": "" }
        ],
        "lastChapter": {
          "array": {
            "at": "span",
            "contains": "最新：",
            "take": { "select": "a" }
          }
        },
        "tags": {
          "array": {
            "at": ".tag-list span.tag",
            "take": { "transform": ["trim"] },
            "first": false,
            "skip": 1
          }
        }
      },
      "chapters": {
        "items": "a.comics-chapters__item[href^=\"/user/page_direct?\"]",
        "index": { "default": "position" },
        "dedupBy": {
          "vars": {
            "sec": { "attr": "href", "transform": ["param:section_slot"] },
            "slot": { "attr": "href", "transform": ["param:chapter_slot"] }
          },
          "template": "{sec}:{slot}"
        },
        "sortBy": [
          { "attr": "href", "transform": ["param:section_slot"] },
          { "attr": "href", "transform": ["param:chapter_slot"] }
        ],
        "title": [{ "select": "span", "transform": ["trim"] }],
        "hidden": {
          "pageUrl": {
            "vars": { "href": { "attr": "href" } },
            "template": "{base}{href}"
          }
        }
      }
    },
    "images": {
      "request": [{ "name": "page", "url": "{pageUrl}" }],
      "items": "amp-img[id^=\"chapter-img-\"]",
      "url": { "attr": "src" }
    }
  }
}

